def read_export(path: Path, unknown_label: str) -> list[Record]:
    """Read an export of any system into records, in file order.

    Every row becomes a record; nothing is filtered.  Amounts are converted to
    dollars and dates to :class:`datetime.date` by the reader for that system.
    """
    source = Path(path)
    system = detect_system(source)
    reader = READERS[system]
    _log.info("reading %s as system %s", source.name, system)
    records: list[Record] = []
    for row in reader.read_rows(source):
        try:
            records.append(reader.to_record(row, unknown_label))
        except LedgerParseError as exc:
            raise LedgerParseError(f"{source.name}: {exc}") from exc
    return records"}]
